    37→/**
    38→ * Specifies how input rows should be filtered and transforms. There are two parts: a "filter" (which can filter out
    39→ * input rows) and "transforms" (which can add fields to input rows). Filters may refer to fields generated by
    40→ * a transform.
    41→ *
    42→ * See {@link Transform} for details on how each transform works.
    43→ */
    44→public class TransformSpec
    45→{
    46→  public static final TransformSpec NONE = new TransformSpec(null, null);
    47→
    48→  private final DimFilter filter;
    49→  private final List<Transform> transforms;
    50→
    51→  @JsonCreator
    52→  public TransformSpec(
    53→      @JsonProperty("filter") final DimFilter filter,
    54→      @JsonProperty("transforms") final List<Transform> transforms
    55→  )
    56→  {
    57→    this.filter = filter;
    58→    this.transforms = transforms == null ? ImmutableList.of() : transforms;
    59→
    60→    // Check for name collisions.
    61→    final Set<String> seen = new HashSet<>();
    62→    for (Transform transform : this.transforms) {
    63→      if (!seen.add(transform.getName())) {
    64→        throw new ISE("Transform name '%s' cannot be used twice", transform.getName());
    65→      }
    66→    }
    67→  }
    68→
    69→  public static <T> TransformSpec fromInputRowParser(final InputRowParser<T> parser)
    70→  {
    71→    // Hack: some firehoses and input specs must extract transformSpec from the parser, since they do not
    72→    // actually use the parser, but still must respect the transformSpec. This method should extract whatever
    73→    // transformSpec "decorate" had put in.
    74→
    75→    if (parser instanceof TransformingInputRowParser) {
    76→      return ((TransformingInputRowParser) parser).getTransformSpec();
    77→    } else if (parser instanceof TransformingStringInputRowParser) {
    78→      return ((TransformingStringInputRowParser) parser).getTransformSpec();
    79→    } else {
    80→      throw new ISE("Parser was not decorated, but should have been");
    81→    }
    82→  }
    83→
    84→  @JsonProperty
    85→  @Nullable
    86→  public DimFilter getFilter()
    87→  {
    88→    return filter;
    89→  }
    90→
    91→  @JsonProperty
    92→  public List<Transform> getTransforms()
    93→  {
    94→    return transforms;
    95→  }
    96→
    97→  public <T> InputRowParser<T> decorate(final InputRowParser<T> parser)
    98→  {
    99→    // Always decorates, even if the transformSpec is a no-op. This is so fromInputRowParser can insist that the
   100→    // parser is a transforming parser, and possibly help detect coding errors where someone forgot to call "decorate".
   101→
   102→    if (parser instanceof StringInputRowParser) {
   103→      // Hack to support the fact that some callers use special methods in StringInputRowParser, such as
   104→      // parse(String) and startFileFromBeginning.
   105→      return (InputRowParser<T>) new TransformingStringInputRowParser(
   106→          parser.getParseSpec(),
   107→          ((StringInputRowParser) parser).getEncoding(),
   108→          this
   109→      );
   110→    } else {
   111→      return new TransformingInputRowParser<>(parser, this);
   112→    }
   113→  }
   114→
   115→  public InputSourceReader decorate(InputSourceReader reader)
   116→  {
   117→    return new TransformingInputSourceReader(reader, toTransformer());
   118→  }
   119→
   120→  /**
   121→   * Create a {@link Transformer} from this TransformSpec, when the rows to be transformed do not have a known
   122→   * signature.
   123→   */
   124→  public Transformer toTransformer()
   125→  {
   126→    return new Transformer(this);
   127→  }
   128→
   129→  @Override
   130→  public boolean equals(final Object o)
   131→  {
   132→    if (this == o) {
   133→      return true;
   134→    }
   135→    if (o == null || getClass() != o.getClass()) {
   136→      return false;
   137→    }
   138→    final TransformSpec that = (TransformSpec) o;
   139→    return Objects.equals(filter, that.filter) &&
   140→           Objects.equals(transforms, that.transforms);
   141→  }
   142→
   143→  @Override
   144→  public int hashCode()
   145→  {
   146→    return Objects.hash(filter, transforms);
   147→  }
   148→
   149→  @Override
   150→  public String toString()
   151→  {
   152→    return "TransformSpec{" +
   153→           "filter=" + filter +
   154→           ", transforms=" + transforms +
   155→           '}';
   156→  }
   157→}
