    33→
    34→import javax.annotation.Nullable;
    35→import java.util.ArrayList;
    36→import java.util.HashMap;
    37→import java.util.List;
    38→import java.util.Map;
    39→import java.util.Objects;
    40→
    41→/**
    42→ *
    43→ */
    44→public class Transformer
    45→{
    46→  private final Map<String, RowFunction> transforms = new HashMap<>();
    47→  private final ThreadLocal<Row> rowSupplierForValueMatcher = new ThreadLocal<>();
    48→  private final ValueMatcher valueMatcher;
    49→
    50→  Transformer(final TransformSpec transformSpec)
    51→  {
    52→    for (final Transform transform : transformSpec.getTransforms()) {
    53→      transforms.put(transform.getName(), transform.getRowFunction());
    54→    }
    55→
    56→    if (transformSpec.getFilter() != null) {
    57→      valueMatcher = transformSpec.getFilter().toFilter()
    58→                                  .makeMatcher(
    59→                                      RowBasedColumnSelectorFactory.create(
    60→                                          RowAdapters.standardRow(),
    61→                                          rowSupplierForValueMatcher::get,
    62→                                          RowSignature.empty(),
    63→                                          false
    64→                                      )
    65→                                  );
    66→    } else {
    67→      valueMatcher = null;
    68→    }
    69→  }
    70→
    71→  /**
    72→   * Transforms an input row, or returns null if the row should be filtered out.
    73→   *
    74→   * @param row the input row
    75→   */
    76→  @Nullable
    77→  public InputRow transform(@Nullable final InputRow row)
    78→  {
    79→    if (row == null) {
    80→      return null;
    81→    }
    82→
    83→    final InputRow transformedRow;
    84→
    85→    if (transforms.isEmpty()) {
    86→      transformedRow = row;
    87→    } else {
    88→      transformedRow = new TransformedInputRow(row, transforms);
    89→    }
    90→
    91→    if (valueMatcher != null) {
    92→      rowSupplierForValueMatcher.set(transformedRow);
    93→      if (!valueMatcher.matches()) {
    94→        return null;
    95→      }
    96→    }
    97→
    98→    return transformedRow;
    99→  }
   100→
   101→  @Nullable
   102→  public InputRowListPlusRawValues transform(@Nullable final InputRowListPlusRawValues row)
   103→  {
   104→    if (row == null) {
   105→      return null;
   106→    }
   107→
   108→    final InputRowListPlusRawValues inputRowListPlusRawValues;
   109→
   110→    if (transforms.isEmpty() || row.getInputRows() == null) {
   111→      inputRowListPlusRawValues = row;
   112→    } else {
   113→      final List<InputRow> originalRows = row.getInputRows();
   114→      final List<InputRow> transformedRows = new ArrayList<>(originalRows.size());
   115→      for (InputRow originalRow : originalRows) {
   116→        transformedRows.add(new TransformedInputRow(originalRow, transforms));
   117→      }
   118→      inputRowListPlusRawValues = InputRowListPlusRawValues.of(transformedRows, row.getRawValues());
   119→    }
   120→
   121→    if (valueMatcher != null) {
   122→      if (inputRowListPlusRawValues.getInputRows() != null) {
   123→        final List<InputRow> filteredRows = new ArrayList<>(inputRowListPlusRawValues.getInputRows().size());
   124→        for (InputRow inputRow : inputRowListPlusRawValues.getInputRows()) {
   125→          rowSupplierForValueMatcher.set(inputRow);
   126→          if (valueMatcher.matches()) {
   127→            filteredRows.add(inputRow);
   128→          }
   129→        }
   130→        return InputRowListPlusRawValues.of(filteredRows, row.getRawValues());
   131→      }
   132→    }
   133→
   134→    return inputRowListPlusRawValues;
   135→  }
   136→
   137→  public static class TransformedInputRow implements InputRow
   138→  {
   139→    private final InputRow row;
   140→    private final Map<String, RowFunction> transforms;
   141→
   142→    public TransformedInputRow(final InputRow row, final Map<String, RowFunction> transforms)
   143→    {
   144→      this.row = row;
   145→      this.transforms = transforms;
   146→    }
   147→
   148→    @Override
   149→    public List<String> getDimensions()
   150→    {
   151→      return row.getDimensions();
   152→    }
   153→
   154→    @Override
   155→    public long getTimestampFromEpoch()
   156→    {
   157→      final RowFunction transform = transforms.get(ColumnHolder.TIME_COLUMN_NAME);
   158→      if (transform != null) {
   159→        //noinspection ConstantConditions time column is never null
   160→        return Rows.objectToNumber(ColumnHolder.TIME_COLUMN_NAME, transform.eval(row), true).longValue();
   161→      } else {
   162→        return row.getTimestampFromEpoch();
   163→      }
   164→    }
   165→
   166→    @Override
   167→    public DateTime getTimestamp()
   168→    {
   169→      final RowFunction transform = transforms.get(ColumnHolder.TIME_COLUMN_NAME);
   170→      if (transform != null) {
   171→        return DateTimes.utc(getTimestampFromEpoch());
   172→      } else {
   173→        return row.getTimestamp();
   174→      }
   175→    }
   176→
   177→    @Override
   178→    public List<String> getDimension(final String dimension)
   179→    {
   180→      final RowFunction transform = transforms.get(dimension);
   181→      if (transform != null) {
   182→        return Rows.objectToStrings(transform.eval(row));
   183→      } else {
   184→        return row.getDimension(dimension);
   185→      }
   186→    }
   187→
   188→    @Override
   189→    public Object getRaw(final String column)
   190→    {
   191→      final RowFunction transform = transforms.get(column);
   192→      if (transform != null) {
   193→        return transform.eval(row);
   194→      } else {
   195→        return row.getRaw(column);
   196→      }
   197→    }
   198→
   199→    @Override
   200→    public Number getMetric(final String metric)
   201→    {
   202→      final RowFunction transform = transforms.get(metric);
   203→      if (transform != null) {
   204→        return Rows.objectToNumber(metric, transform.eval(row), true);
   205→      } else {
   206→        return row.getMetric(metric);
   207→      }
   208→    }
   209→
   210→    @Override
   211→    public boolean equals(final Object o)
   212→    {
   213→      if (this == o) {
   214→        return true;
   215→      }
   216→      if (o == null || getClass() != o.getClass()) {
   217→        return false;
   218→      }
   219→      final TransformedInputRow that = (TransformedInputRow) o;
   220→      return Objects.equals(row, that.row) &&
   221→             Objects.equals(transforms, that.transforms);
   222→    }
   223→
   224→    @Override
   225→    public int hashCode()
   226→    {
   227→      return Objects.hash(row, transforms);
   228→    }
   229→
   230→    @Override
   231→    public int compareTo(final Row o)
   232→    {
   233→      return row.compareTo(o);
   234→    }
   235→
   236→    @Override
   237→    public String toString()
   238→    {
   239→      return "TransformedInputRow{" +
   240→             "row=" + row +
   241→             '}';
   242→    }
   243→  }
   244→}
